package com.flashsale.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="sale_orders", uniqueConstraints=@UniqueConstraint(name="uk_sale_orders_idempotency_key",columnNames="idempotency_key"))
public class SaleOrder { @Id private UUID id; @Column(name="product_id",nullable=false) private String productId; @Column(name="customer_id",nullable=false) private String customerId; @Column(name="idempotency_key",nullable=false,updatable=false) private String idempotencyKey; @Enumerated(EnumType.STRING) @Column(nullable=false) private OrderStatus status; @Column(name="created_at",nullable=false) private Instant createdAt; protected SaleOrder(){} public SaleOrder(UUID id,String productId,String customerId,String idempotencyKey){this.id=id;this.productId=productId;this.customerId=customerId;this.idempotencyKey=idempotencyKey;status=OrderStatus.COMPLETED;createdAt=Instant.now();} public UUID getId(){return id;} public String getProductId(){return productId;} public String getCustomerId(){return customerId;} public String getIdempotencyKey(){return idempotencyKey;} public OrderStatus getStatus(){return status;} public Instant getCreatedAt(){return createdAt;} }
